questionvariables.text:
/*Question variables*/
var_num1:rand_with_step(2,4,1);
var_num2:rand_with_step(5,7,1);
num_func:sqrt(var_num1^2*x^2+var_num2^2);
denom_func:x^4;
question_func:num_func/denom_func;

/*model answer*/
ta:int(question_func,x)+c; 

/*Worked out soln*/
let_x:var_num2*tan(theta)/var_num1; /*Variable name for let x (simplified)*/
diff_letx:diff(let_x)/del(theta); /*derivative of let_xx*/

/*Lets focus on the numerator*/
subst_trig:subst(let_x,x,num_func);
subst_trig1:args(subst_trig)[1];
subst_trig2:factor(subst_trig1);
trig_subst_sec:subst((sec(theta))^2,(tan(theta))^2+1,subst_trig2);
soln_trig_subst_sec:sqrt(trig_subst_sec);
soln_trig_subst_sec1:args(soln_trig_subst_sec)[1];
soln_trig_subst_sec2:args(soln_trig_subst_sec)[2];
soln_trig_subst_sec2a:args(soln_trig_subst_sec2)[1];

num_new_trig_func:soln_trig_subst_sec1*soln_trig_subst_sec2a;
denom_new_trig_func:let_x^4;
new_trig_func:num_new_trig_func/denom_new_trig_func;

sec:1/cos(theta);
tan:sin(theta)/cos(theta);
expr_trig1_func:new_trig_func*diff_letx/del(theta);
subst_trig1_expr:subst(sec,sec(theta),expr_trig1_func);
subst_trig2_expr:(subst(tan,tan(theta),subst_trig1_expr))*del(theta);
simp:true;
let_u:sin(theta);
diff_let_u:diff(let_u)/del(theta);
eqn_interms_u:subst(u,sin(theta),subst_trig2_expr)*1/cos(theta);
eqn_interms_trig:subst(sin(theta),u,int(eqn_interms_u,u))+c;
var_sin_theta:(var_num1*x)/(sqrt((var_num1*x)^2+(var_num2)^2));
var_tan_trig_theta:solve((x=let_x),tan(theta));
tan_trig:var_tan_trig_theta[1];

rhs_tan_trig:rhs(tan_trig^2);
num_rhs_tan_trig:num(rhs_tan_trig);
den_rhs_tan_trig:denom(rhs_tan_trig);
expr1__tan_trig:expand(num_rhs_tan_trig*(1-(sin(theta)^2)));
expr2__tan_trig:expand(den_rhs_tan_trig*(sin(theta))^2);
expression:expr1__tan_trig=expr2__tan_trig;
solve_expression_sin:solve(expression,(sin(theta))^2);
sin_theta_solve_expression:solve_expression_sin[1];
sin_theta_solve_expression_1:rhs(sin_theta_solve_expression);
sin_theta_solve_expression_2:sqrt(sin_theta_solve_expression_1);

tta:subst(sin_theta_solve_expression_2,sin(theta),eqn_interms_trig);

feedbackvariables.text:
/*node1: checking for correct answer*/

/*node2: checking if the student forgot to add constant of integration*/
mistake2:int(question_func,xx);

/*node3: checking if the student subtracted the constant of integration instead of adding*/
mistake3:int(question_func,xx)-c;

/*node4: checking if the student subtracted the constant of integration instead of adding*/
mistake4:diff(question_func);
